import 'package:native_toolchain_cmake/web.dart';

EmscriptenModule? _module;

/// Loads the Emscripten module generated by `hook/build.dart`.
///
/// [scriptUrl] must point to the generated `add.js` asset. [wasmBinary] is
/// optional; when omitted Emscripten fetches `add.wasm` next to the script
/// (or uses the embedded module when built with `singleFile`).
Future<void> initAdd({Uri? scriptUrl, List<int>? wasmBinary}) async {
  if (_module != null) return;
  if (scriptUrl == null) {
    throw ArgumentError('scriptUrl is required on the web.');
  }
  _module = await loadEmscriptenModule(
    scriptUrl: scriptUrl,
    wasmBinary: wasmBinary,
    factoryName: 'addModule',
  );
}

int calculate(int a, int b, {int times = 1}) {
  final module = _module;
  if (module == null) {
    throw StateError('Call initAdd(scriptUrl: ...) before calculate().');
  }
  final result = module.callNum('math_add', args: [a, b]).toInt();
  return result * times;
}
